import React from "react";

export default function About() {
  return (
    <div className="about-page">

      <div className="about-wrapper">

        {/* LEFT SIDE */}
        <div className="about-left">
          <h1>
            About <span className="highlight">Me</span>
          </h1>

          <p>
            I am an enthusiastic and dedicated Information Technology student at 
            <span className="college"> Panimalar Engineering College</span>. 
            I am passionate about building modern digital solutions that are 
            not only functional but also user-friendly and impactful.
          </p>

          <p>
            I enjoy turning ideas into real-world applications by combining 
            creativity with technical skills. I constantly explore new 
            technologies and strive to improve my problem-solving abilities 
            through hands-on projects and continuous learning.
          </p>

          {/* WHAT I DO */}
          <div className="what-i-do">
            <h3>🚀 What I Do</h3>
            <p>
              I focus on developing responsive web applications, designing 
              intuitive user interfaces, and working on innovative projects 
              that solve real-world problems. My goal is to create systems 
              that are efficient, scalable, and meaningful.
            </p>
          </div>

          {/* QUICK STATS */}
          <div className="stats">
            <div className="stat-box">
              <h3>5+</h3>
              <p>Projects</p>
            </div>
            <div className="stat-box">
              <h3>10+</h3>
              <p>Technologies Explored</p>
            </div>
            <div className="stat-box">
              <h3>2+</h3>
              <p>Domains</p>
            </div>
          </div>
        </div>

        {/* RIGHT SIDE */}
        <div className="about-right">

          {/* EDUCATION */}
          <div className="about-card">
            <div className="card-header">
              <h3>🎓 Education</h3>
              <span className="year">2023 – 2027</span>
            </div>
            <p><strong>B.Tech – Information Technology</strong></p>
            <p>Panimalar Engineering College</p>
            <p>
              Gaining strong foundations in software development, database 
              systems, and modern technologies through academic coursework 
              and practical project development.
            </p>
          </div>

          {/* INTERESTS */}
          <div className="about-card">
            <h3>💡 Interests</h3>
            <ul>
              <li>Full Stack Development</li>
              <li>Data Analytics</li>
              <li>UI/UX Design</li>
              <li>Smart System Development</li>
            </ul>
          </div>

        </div>

      </div>

      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 60px 10%;
          font-family: "Poppins", sans-serif;
          background: linear-gradient(135deg, #0f172a, #020617);
          color: white;
        }

        .about-wrapper {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 60px;
        }

        .about-left h1 {
          font-size: 48px;
          margin-bottom: 15px;
        }

        .highlight {
          color: #38BDF8;
        }

        .college {
          color: #7dd3fc;
          font-weight: 600;
        }

        .about-left p {
          color: #cbd5e1;
          line-height: 1.8;
          font-size: 17px;
          margin-bottom: 12px;
        }

        /* WHAT I DO */
        .what-i-do {
          margin-top: 20px;
          padding: 15px;
          border-left: 4px solid #38BDF8;
          background: rgba(255,255,255,0.03);
          border-radius: 8px;
        }

        .what-i-do h3 {
          margin-bottom: 8px;
          color: #38BDF8;
        }

        /* STATS */
        .stats {
          display: flex;
          gap: 20px;
          margin-top: 25px;
        }

        .stat-box {
          background: rgba(255,255,255,0.05);
          padding: 15px;
          border-radius: 12px;
          text-align: center;
          flex: 1;
          border: 1px solid rgba(56,189,248,0.3);
        }

        .stat-box h3 {
          color: #38BDF8;
          font-size: 22px;
        }

        /* RIGHT SIDE */
        .about-right {
          display: flex;
          flex-direction: column;
          gap: 25px;
        }

        .about-card {
          background: rgba(255,255,255,0.05);
          backdrop-filter: blur(10px);
          padding: 25px;
          border-radius: 16px;
          border: 1px solid rgba(56,189,248,0.2);
          transition: 0.4s;
        }

        .about-card:hover {
          transform: translateY(-6px);
          box-shadow: 0 0 30px rgba(56,189,248,0.5);
          border-color: #38BDF8;
        }

        .card-header {
          display: flex;
          justify-content: space-between;
          margin-bottom: 10px;
        }

        .year {
          background: #38BDF8;
          padding: 4px 12px;
          border-radius: 20px;
          font-size: 12px;
          font-weight: bold;
          color: black;
        }

        ul {
          padding-left: 18px;
        }

        li {
          margin-bottom: 6px;
        }

        @media (max-width: 900px) {
          .about-wrapper {
            grid-template-columns: 1fr;
          }

          .stats {
            flex-direction: column;
          }
        }

      `}</style>

    </div>
  );
}
